import{_ as o,o as e,c as i,a2 as r}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Artigo 106｜Refino de Reinos · Reino de Sentimento da Origem · Comparação Detalhada: Facção Predadora vs Facção Simbiótica","description":"","frontmatter":{"title":"Artigo 106｜Refino de Reinos · Reino de Sentimento da Origem · Comparação Detalhada: Facção Predadora vs Facção Simbiótica","no":106,"module":1,"tags":["境界","感元境","掠夺派","共生派","体系对比"],"related":["04-反掠夺主义核心论纲","01-锚点共生文明宣言","14-修炼境界统一划分"]},"headers":[],"relativePath":"pt/106_模块1-感元境-掠夺派vs共生派对比.md","filePath":"pt/106_模块1-感元境-掠夺派vs共生派对比.md"}'),t={name:"pt/106_模块1-感元境-掠夺派vs共生派对比.md"};function d(s,a,n,c,m,l){return e(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="artigo-106-reino-de-sentimento-da-origem-comparacao-detalhada-entre-faccao-predadora-e-faccao-simbiotica" tabindex="-1">Artigo 106｜Reino de Sentimento da Origem: Comparação Detalhada entre Facção Predadora e Facção Simbiótica <a class="header-anchor" href="#artigo-106-reino-de-sentimento-da-origem-comparacao-detalhada-entre-faccao-predadora-e-faccao-simbiotica" aria-label="Permalink to &quot;Artigo 106｜Reino de Sentimento da Origem: Comparação Detalhada entre Facção Predadora e Facção Simbiótica&quot;">​</a></h1><blockquote><p>Módulo: Módulo Um · Refino Profundo de Reinos | Base de Referência: Documentos 04, 01, 14</p></blockquote><h2 id="introducao-mesmo-ponto-de-partida-dois-caminhos-opostos" tabindex="-1">Introdução: Mesmo Ponto de Partida, Dois Caminhos Opostos <a class="header-anchor" href="#introducao-mesmo-ponto-de-partida-dois-caminhos-opostos" aria-label="Permalink to &quot;Introdução: Mesmo Ponto de Partida, Dois Caminhos Opostos&quot;">​</a></h2><p>O Reino de Sentimento da Origem é o ponto de partida dos nove reinos e também a primeira encruzilhada onde a vida das Dez Mil Raças enfrenta a escolha de rota. Mesmo talento, mesmo cosmo, mesmo a expressão &quot;perceber energia&quot;, a Facção Predadora e a Facção Simbiótica dão respostas diametralmente opostas. Este artigo, tomando o Reino de Sentimento da Origem como fatia, compara sistematicamente as diferenças fundamentais entre as duas rotas em caminho, custo e destino, e responde a uma questão central: por que o teto da Facção Predadora está sempre abaixo do piso da Facção Simbiótica?</p><p>Os Seis Axiomas Supremos são o divisor de águas entre as duas rotas: o Axioma do Antipredação — a fonte do primeiro gole de energia define a rota; o Axioma da República das Dez Mil Raças — aos olhos da Facção Simbiótica as Dez Mil Raças são co-cultivadoras, aos olhos da Facção Predadora todos os seres são presas; o Axioma da Ascensão Dimensional Coletiva — a Facção Simbiótica torna-se forte para ascender, a Facção Predadora torna-se forte para usufruir sozinha, evitando o grande talento em uso ínfimo; o Axioma da Autodisciplina Causal — toda operação da Facção Simbiótica é registrável, rastreável e corrigível; o Axioma da Prioridade da Lei — o quadro legal de comparação entre Facção Predadora e Facção Simbiótica é estável e autocoerente, sem retcon por conveniência narrativa, podendo expandir-se infinitamente sem colapsar. A Lei da Igualdade Infinita Universal para todos os Seres estabelece que todos carregam fundamentalmente o Poder Infinito Fundamental; os cultivadores preguiçosos mantêm um infinito basal de garantia e não serão eliminados pelos tempos, enquanto os ambiciosos e os Jovens Soberanos podem sobrepor infinitos de nível superior; a origem infinita é inerente a todos, e a predação naturalmente perde o sentido.</p><h2 id="i-tabela-de-comparacao-sistematica" tabindex="-1">I. Tabela de Comparação Sistemática <a class="header-anchor" href="#i-tabela-de-comparacao-sistematica" aria-label="Permalink to &quot;I. Tabela de Comparação Sistemática&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Dimensão</th><th>Facção Predadora · Reino de Sentimento da Origem</th><th>Facção Simbiótica · Reino de Sentimento da Origem</th></tr></thead><tbody><tr><td>Fonte de energia</td><td>Devorar energia alheia, roubar oportunidades de percepção alheia</td><td>Absorver energia cósmica livre por métodos regulares, ciclo bidirecional da origem das Dez Mil Raças</td></tr><tr><td>Modo de percepção</td><td>Roubar resultados de percepção alheia, rápido mas grosseiro</td><td>Vivenciar o despertar da percepção, base pura</td></tr><tr><td>Custo de ruptura</td><td>Esgotar o talento, origem impura, perigos amplificados ao longo do caminho</td><td>Custo real + monitoração de âncora, reparável e recomeçável</td></tr><tr><td>Ambiente de supervisão</td><td>Lei da selva, sem supervisão, sem responsabilidade</td><td>Rede Ālaya + supervisão multicamadas de proteção de cadeia completa</td></tr><tr><td>Posição social</td><td>Presa ou caçador, uma das duas</td><td>Co-construtor, Um Caminho para Todos</td></tr><tr><td>Destino</td><td>Teto de eficiência: depois de um passo não anda mais, não toca o Reino da Origem</td><td>Reino da Origem e além, peso civilizacional cresce com a contribuição</td></tr></tbody></table><h2 id="ii-as-tres-falacias-da-faccao-predadora-projetadas-no-reino-de-sentimento-da-origem" tabindex="-1">II. As Três Falácias da Facção Predadora Projetadas no Reino de Sentimento da Origem <a class="header-anchor" href="#ii-as-tres-falacias-da-faccao-predadora-projetadas-no-reino-de-sentimento-da-origem" aria-label="Permalink to &quot;II. As Três Falácias da Facção Predadora Projetadas no Reino de Sentimento da Origem&quot;">​</a></h2><p>As três falácias do predacionismo argumentadas no Documento 04 (Tesess Centrais do Antipredação) já projetam-se integralmente no Reino de Sentimento da Origem:</p><ol><li>Falácia cosmológica: tratar o cosmo como um campo de caça limitado — aprender a &quot;roubar&quot; já no Reino de Sentimento da Origem equivale a, desde o primeiro dia, reconhecer que a evolução é jogo de soma zero</li><li>Falácia ética: colocar o direito evolutivo do forte acima do direito de existência do fraco — uma vez aberta a &quot;devoração&quot; no Reino de Sentimento da Origem, não há volta</li><li>Falácia de eficiência: crer que a predação é a mais rápida — a percepção roubada no Reino de Sentimento da Origem traz os resquícios da vontade do dono original; o custo de refino posterior supera de longe o cultivo próprio</li></ol><p>O cultivador da Facção Predadora no Reino de Sentimento da Origem, com a velocidade mais rápida esgota o mais caro fundamento; o cultivador da Facção Simbiótica no Reino de Sentimento da Origem, com o ritmo mais estável deposita o capital mais espesso.</p><h2 id="iii-predador-ilustrado-nem-a-bondade-salva-a-rota-predatoria" tabindex="-1">III. Predador Ilustrado: Nem a Bondade Salva a Rota Predatória <a class="header-anchor" href="#iii-predador-ilustrado-nem-a-bondade-salva-a-rota-predatoria" aria-label="Permalink to &quot;III. Predador Ilustrado: Nem a Bondade Salva a Rota Predatória&quot;">​</a></h2><p>É preciso enfrentar um objeto complexo: o &quot;predador ilustrado&quot; — aqueles fortes relativamente bondosos, até sinceramente dispostos a proteger todos os seres. Suas características: não fazem o mal por iniciativa, estão dispostos a dar abrigo, são sinceros com os próximos, mas todo o sistema ainda se assenta sobre uma base predatória — monopolizar o grande caminho superior, usufruir sozinho a permissão de origem, sob o nome de &quot;proteger&quot; praticar o &quot;dar&quot;.</p><p>No contexto do Reino de Sentimento da Origem, a educação tipo &quot;predador ilustrado&quot; é: alimentar o gênio com os melhores recursos, mas nunca verdadeiramente lhe ceder o caminho — porque o &quot;caminho&quot; em si é um artigo monopolizado. Isto explica por que mesmo os fortes bondosos não alcançam a altura da civilização supramultiversal: ele está no topo do sistema predatório, e o teto do sistema predatório é o seu próprio teto.</p><h2 id="iv-por-que-a-faccao-predadora-esta-condenada-a-regressao-historica" tabindex="-1">IV. Por Que a Facção Predadora Está Condenada à Regressão Histórica <a class="header-anchor" href="#iv-por-que-a-faccao-predadora-esta-condenada-a-regressao-historica" aria-label="Permalink to &quot;IV. Por Que a Facção Predadora Está Condenada à Regressão Histórica&quot;">​</a></h2><p>O destino estrutural da civilização da Facção Predadora é: quando o forte cai, a civilização regide. Todo o funcionamento do sistema depende da boa vontade e do poder do indivíduo no topo — ele vivo, a ordem mal se mantém; ele fora, o campo de caça reinicia. Esta &quot;dependência de ponto único&quot; não é uma falha moral, mas estrutural: o sistema predatório jamais escreveu a ordem em instituições, apenas apostou a ordem no indivíduo forte.</p><p>Esta é a forma original da &quot;unicidade do protagonista&quot;: a sobrevivência da civilização depende de uma pessoa só. E a resposta da Civilização Simbiótica da Âncora é escrever a paz em instituições e no Netz der Gesetze (âncora, lei, conselho, contrato de produção), mesmo quando o mais forte Potência Suprema do Plano cai, a rede simbiótica continua funcionando.</p><h2 id="v-o-canalha-justo-limiar-de-ascensao-e-nova-rota" tabindex="-1">V. O Canalha Justo: Limiar de Ascensão e Nova Rota <a class="header-anchor" href="#v-o-canalha-justo-limiar-de-ascensao-e-nova-rota" aria-label="Permalink to &quot;V. O Canalha Justo: Limiar de Ascensão e Nova Rota&quot;">​</a></h2><p>Para saltar da Facção Predadora para a Facção Simbiótica, é preciso cruzar um limiar de ascensão chamado &quot;o canalha justo&quot;: ousar rasgar o antigo direito consagrado, derrubar a lógica de base do sistema antigo, não temer a pressão dos grupos de interesses estabelecidos, e reescrever o contrato justo de simbiose.</p><p>O protagonista Lín Hào é justamente o representante desta rota: ele nasceu com origem deficiente, seguir a rota da alma bestial só prejudicaria o corpo, é vítima das regras antigas, não beneficiário — forçado a reconstruir as regras, deduziu a Rota D · Anel de Alma da Regra Artificial do Rén Zú, substituindo a caça e colheita de anéis por leis artificiais, transformando-se de vítima do sistema predatório em reconstrutor da civilização simbiótica. O Reino de Sentimento da Origem é a entrada mais antiga deste limiar: alguém que já no ponto de partida escolhe a rota simbiótica está, já mais próximo da civilização supramultiversal do que o &quot;predador ilustrado&quot; preso no topo do sistema predatório.</p><h2 id="vi-cinco-pontos-centrais" tabindex="-1">VI. Cinco Pontos Centrais <a class="header-anchor" href="#vi-cinco-pontos-centrais" aria-label="Permalink to &quot;VI. Cinco Pontos Centrais&quot;">​</a></h2><ul><li>Antidesperdício de energia: a Facção Predadora desperdiça o talento em uma internal destrutiva, a Facção Simbiótica investe o talento na construção incremental</li><li>Antipredação: a divisão essencial das duas rotas está no primeiro gole de energia no Reino de Sentimento da Origem</li><li>Comparação com o teto Táng Luó: o &quot;bem-estar&quot; tipo Táng Luó ainda é sistema de dádiva — todos os seres dependem dos fortes, não são construção compartilhada; a Facção Simbiótica tem Um Caminho para Todos, ninguém depende de ninguém</li><li>Cobertura total das Dez Mil Raças: aos olhos da Facção Predadora todos os seres são presas e ferramentas, aos olhos da Facção Simbiótica as Dez Mil Raças são co-cultivadoras — a cobertura de 99% não tem exceções</li><li>Abertura total supramultiplanetária: a Facção Predadora monopoliza tudo, a Facção Simbiótica desde o Reino de Sentimento da Origem abre todos os níveis</li></ul><h2 id="conclusao" tabindex="-1">Conclusão <a class="header-anchor" href="#conclusao" aria-label="Permalink to &quot;Conclusão&quot;">​</a></h2><p>A comparação entre Facção Predadora e Facção Simbiótica no Reino de Sentimento da Origem condensa o conflito central de toda a história cósmica: a predação traz fortes efêmeros e regressão eterna, a simbiose traz prosperidade duradoura e ascensão coletiva. O cultivador da Facção Predadora no Reino de Sentimento da Origem esforça-se ao máximo para vencer na linha de largada, só para descobrir que a linha de chegada carrega o seu próprio teto; o cultivador da Facção Simbiótica no Reino de Sentimento da Origem dá o primeiro passo com firmeza, e descobre que o fim do caminho é a Esfera Supra-Multiversal do Âncora Equilibrada. A escolha está decidida no ponto de partida — isto não é destino, é axioma.</p><h2 id="relacionados" tabindex="-1">Relacionados <a class="header-anchor" href="#relacionados" aria-label="Permalink to &quot;Relacionados&quot;">​</a></h2><ul><li>Documentos relacionados: <a href="./04-反掠夺主义核心论纲.html">04-反掠夺主义核心论纲</a> · <a href="./01-锚点共生文明宣言.html">01-锚点共生文明宣言</a> · <a href="./14-修炼境界统一划分.html">14-修炼境界统一划分</a></li><li>Site oficial: <a href="https://faker210.github.io/hengyuan-cosmos/zh/" target="_blank" rel="noreferrer">https://faker210.github.io/hengyuan-cosmos/zh/</a></li></ul>',26)])])}const h=o(t,[["render",d]]);export{p as __pageData,h as default};
